#!/bin/bash\n\n# Colors for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nNC='\\033[0m' # No Color\n\necho -e \"${GREEN}========================================${NC}\"\necho -e \"${GREEN}Multi-Agent AI Dev Assistant Setup${NC}\"\necho -e \"${GREEN}========================================${NC}\"\n\n# Check if Docker is installed\nif ! command -v docker &> /dev/null; then\n    echo -e \"${RED}Docker is not installed. Installing Docker...${NC}\"\n    if [[ \"$OSTYPE\" == \"darwin\"* ]]; then\n        # macOS\n        /bin/bash -c \"$(curl -fsSL https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh)\"\n        brew install --cask docker\n    elif [[ \"$OSTYPE\" == \"linux-gnu\"* ]]; then\n        # Linux\n        curl -fsSL https://get.docker.com -o get-docker.sh\n        sudo sh get-docker.sh\n    fi\nelse\n    echo -e \"${GREEN}✓ Docker is installed${NC}\"\nfi\n\n# Check if Docker Compose is installed\nif ! command -v docker-compose &> /dev/null; then\n    echo -e \"${YELLOW}Installing Docker Compose...${NC}\"\n    sudo curl -L \"https://github.com/docker/compose/releases/latest/download/docker-compose-$(uname -s)-$(uname -m)\" -o /usr/local/bin/docker-compose\n    sudo chmod +x /usr/local/bin/docker-compose\nelse\n    echo -e \"${GREEN}✓ Docker Compose is installed${NC}\"\nfi\n\n# Create .env files\necho -e \"${YELLOW}\\nSetting up environment variables...${NC}\"\n\n# Backend .env\nif [ ! -f server/.env ]; then\n    cat > server/.env << 'EOF'\nPORT=5000\nNODE_ENV=development\nLOG_LEVEL=info\n\n# Database\nMONGODB_URI=mongodb://mongodb:27017/ai-dev-assistant\n\n# Redis\nREDIS_URL=redis://redis:6379\n\n# LLM Services (Add your keys here)\nOPENAI_API_KEY=sk-your-openai-key-here\nCLAUDE_API_KEY=your-claude-key-here\nLLM_MODEL=gpt-3.5-turbo\n\n# Search Services (Add your keys here)\nSERPAPI_API_KEY=your-serpapi-key-here\nGOOGLE_API_KEY=your-google-key-here\nGOOGLE_SEARCH_ENGINE_ID=your-search-engine-id\nSEARCH_ENGINE=serpapi\n\n# CORS\nCORS_ORIGIN=http://localhost:5173\n\n# Frontend URL\nFRONTEND_URL=http://localhost:5173\nEOF\n    echo -e \"${GREEN}✓ Created server/.env${NC}\"\nelse\n    echo -e \"${YELLOW}✓ server/.env already exists${NC}\"\nfi\n\n# Frontend .env\nif [ ! -f client/.env ]; then\n    cat > client/.env << 'EOF'\nVITE_API_URL=http://localhost:5000\nVITE_SOCKET_URL=http://localhost:5000\nEOF\n    echo -e \"${GREEN}✓ Created client/.env${NC}\"\nelse\n    echo -e \"${YELLOW}✓ client/.env already exists${NC}\"\nfi\n\necho -e \"\\n${YELLOW}========================================${NC}\"\necho -e \"${YELLOW}IMPORTANT: Add Your API Keys${NC}\"\necho -e \"${YELLOW}========================================${NC}\"\necho -e \"${YELLOW}Edit server/.env and add:${NC}\"\necho -e \"  1. OPENAI_API_KEY - Get from https://platform.openai.com/api-keys\"\necho -e \"  2. SERPAPI_API_KEY - Get from https://serpapi.com/dashboard\"\necho -e \"\\n${YELLOW}Then run:${NC}\"\necho -e \"${GREEN}  docker-compose up${NC}\"\necho -e \"\\n${YELLOW}App will be available at:${NC}\"\necho -e \"${GREEN}  Frontend: http://localhost:5173${NC}\"\necho -e \"${GREEN}  Backend: http://localhost:5000${NC}\"\necho -e \"${YELLOW}========================================${NC}\"\n"